const body = $json.body || $json;
const expected = {
  source: 'quoteFinance.ts + Transform QuoteBuilder1',
  recalculate_finance: false,
  vat_rate: 0.2,
  contingency_rate: 0.0225,
  staff_hours_buffer: 3,
  min_billable_hours: 4,
  contact_defaults: {
    contact_name: 'Katherine Bulaon',
    contact_title: 'Client Relationship Manager',
    contact_phone: '020 8323 5827',
    contact_email: 'sales@westendonthethames.com'
  },
  upgradeIdMap: {
    'Live DJ': 'live_dj', Saxophonist: 'saxophonist', Karaoke: 'karaoke',
    'Photo Booth': 'photo_booth', 'Close-up Magician': 'close_up_magician',
    'Branded Vessel Flag': 'branded_vessel_flag', 'Acoustic Artist': 'acoustic_artist',
    'Jazz and Sax Duo': 'jazz_sax_duo', 'Additional Hour on Board': 'extra_hour',
    'Casino Table with Croupier': 'casino_table', 'Social Media Highlight Reel': 'social_highlight_reel',
    'Mingling Tour Guide': 'mingling_guide', 'Bespoke Logo Bunting': 'logo_bunting',
    'Unlimited Drinks (4 hrs)': 'unlimited_drinks', 'Drink Tokens': 'drink_tokens',
    'Street Food Upgrade': 'street_food_upgrade'
  }
};
const transformSource = String(body.transformSource || body.transformQuoteBuilder1 || '');
if (!transformSource.trim()) {
  return [{ json: {
    ok: false,
    drifts: [],
    failureEvent: { type: 'FailureEvent', source: 'ContractSync', reason: 'missing transformSource', httpStatus: 400 },
    expected
  } }];
}
const prompt = [
  'Compare quoteFinance.ts contract vs n8n Transform QuoteBuilder1 source.',
  'Flag drifts in: contact defaults, upgradeIdMap keys/ids, VAT/contingency, and any finance recalculation.',
  'Never propose changing money formulas — only report parity.',
  'Return JSON {"ok":boolean,"drifts":[{"area":"string","expected":"string","found":"string","severity":"low|medium|high"}]}',
  'EXPECTED CONTRACT:',
  JSON.stringify(expected, null, 2),
  'TRANSFORM SOURCE:',
  transformSource.slice(0, 12000)
].join('\n');
return [{ json: { prompt, expected, ok: true } }];
